window.AAQ_ASSIGN = {"unit": 3, "title": "Design for Construction and the Built Environment", "aims": [{"aim": "A", "title": "Explore how construction design and building concepts and processes contribute to a building’s fitness for purpose"}, {"aim": "B", "title": "Produce a building design to meet requirements of a specific client/end user brief"}, {"aim": "C", "title": "Review the success of own building design in meeting requirements of a specific client/end user brief"}], "criteria": [{"code": "A.P1", "aims": "A", "grade": "P", "n": 1, "text": "Outline the factors that can impact on the potential design from the client brief including sustainability requirements."}, {"code": "A.M1", "aims": "A", "grade": "M", "n": 1, "text": "Assess the factors that can impact on the potential design from the client brief including supported reasons for sustainability requirements and ways in which some limitations can be overcome."}, {"code": "A.D1", "aims": "A", "grade": "D", "n": 1, "text": "Evaluate the factors that can impact on the potential design from the client brief including sustainability requirements informed by research, justifying how any limitations can be overcome."}, {"code": "B.P2", "aims": "B", "grade": "P", "n": 2, "text": "Produce a building design that is realistic and workable, using manual techniques and CAD, with annotated sketches that addresses some client/end user requirements showing some consideration of the initial project brief, covering some key project information."}, {"code": "B.P3", "aims": "B", "grade": "P", "n": 3, "text": "Produce a design statement to support the drawings to show how the design satisfies the client brief."}, {"code": "B.M2", "aims": "B", "grade": "M", "n": 2, "text": "Discuss the selection and use of design strategies to inform decisions, presenting ideas in the design statement that show sound consideration for the client/end user requirements and initial project brief and a sound understanding of relevant materials, processes and techniques."}, {"code": "B.D2", "aims": "B", "grade": "D", "n": 2, "text": "Justify the selection and use of design strategies to inform decisions, presenting ideas in the design statement that show an in-depth consideration for the client/end user requirements and initial project brief and an in-depth understanding of relevant materials, processes and techniques."}, {"code": "C.P4", "aims": "C", "grade": "P", "n": 4, "text": "Review own building design in relation to how well the methods of construction chosen, material choices, the final layout, design and sustainability requirements meet the client brief."}, {"code": "C.M3", "aims": "C", "grade": "M", "n": 3, "text": "Discuss own building design and considerations made in relation to the methods of construction chosen, material choices, the final layout, design and sustainability requirements satisfy the client brief."}, {"code": "C.D3", "aims": "C", "grade": "D", "n": 3, "text": "Evaluate own building design and considerations made in relation to the methods of construction chosen, material choices, the final layout, design and sustainability requirements satisfy the client brief, justifying decisions made and including areas for improvement."}], "guidance": [{"aims": "A", "paras": ["For distinction standard, students will evaluate the factors that influence design and development, and consider in depth how these can impact on the final design. They will provide a justification on how to overcome limitations. Students will make use of developed technical vocabulary in their work. Their evaluation will be informed by research into the site, ground conditions, suitable methods of construction, specific locality of the site including planning restraints/limitations, existing housing styles, house prices and any other relevant information, including sustainability requirements. For merit standard, students will assess the factors that influence design and development, and consider how these can impact on the final design. They will provide ways in which to overcome limitations. Students will make use of some technical vocabulary in their work. Their assessment will be based on research made to the site, ground conditions, suitable methods of construction, specific locality of the site including planning restraints/limitations, existing housing styles, house prices and any other relevant information, including sustainability requirements. For pass standard, students will outline the factors that influence design and development, with some consideration of how these can impact on the final design. They will make some use of appropriate technical vocabulary in their work. Students’ work will demonstrate that they will have done some research into the site, ground conditions, suitable methods of construction, specific locality of the site including planning restraints/limitations, existing housing styles, house prices and any other relevant information, including sustainability requirements."]}, {"aims": "B", "paras": ["For distinction standard, students will be able to select, use and interpret most of the relevant information in the context of a scenario, showing a balanced consideration of this information with minimal errors or omissions. They will be able to analyse the spatial requirements of a project and provide detailed justifications of suitable forms of construction to produce a design that communicates design intentions with clarity and comprehensively addresses the project brief. Students use annotations that clearly explain the key features and operation of the design.", "They will produce the design using industry standards and set of drawings and design documentation that clearly demonstrates and justifies design decisions to meet the brief. Students can produce an accurate and complete model that appropriately addresses the scenario requirements and provide printouts of 3D rendered views. For merit standard, students will be able to select, use and interpret relevant information in the context of a scenario. They will be able to consider the spatial requirements of a project and consider suitable forms of construction to produce a design that communicates design intentions with clarity and addresses aspects of the initial project brief, with some use of annotations. Students will produce a comprehensive set of design drawings and supporting annotations and design statements detailing how the designs meet the client brief. They can produce a model that addresses most aspects of the scenario requirements and provide printouts of 3D rendered views. For pass standard, students will be able to select, use and interpret relevant information in the context of a scenario to produce a design. They will be able to consider the spatial requirements of a project and consider suitable forms of construction to produce a design that communicates design intentions with clarity and addresses aspects of the project brief, with some use of annotations. Students will produce a building design that is realistic and workable, using freehand techniques and CAD, with annotated sketches and design statement that addresses some client/end user requirements showing some consideration of the project brief, covering some key project information. They can produce a model that addresses some aspects of the scenario requirements and provide printouts of 3D rendered views, but will have omissions and lack detail."]}, {"aims": "C", "paras": ["For distinction standard, students will provide a detailed critical evaluation of their building design reviewing the whole design process from the initial reading of the client brief through to the final design drawings and supporting statements. They will consider how their design satisfies the client requirements for the site. They will justify decisions made and include areas for improvement. For merit standard, students will provide a detailed discussion of their building design reviewing the whole design process from the initial reading of the client brief through to the final design drawings and supporting statements. They will consider how their design satisfies the client requirements for the site and changes they would make if they were able to do it again. For pass standard, students will provide a review of their building design looking at the whole design process from the initial reading of the client brief through to the final design drawings and supporting statements. They will consider how their design satisfies the client requirements for the site and make little regard to changes they would make if they were able to do it again."]}]};
